import unittest
from candidate import is_multiply_prime

class TestIsMultiplyPrime(unittest.TestCase):

    def test_is_multiply_prime_of_three_primes(self):
        self.assertTrue(is_multiply_prime(30))  # 2 * 3 * 5

    def test_is_multiply_prime_with_one_prime(self):
        self.assertFalse(is_multiply_prime(30))  # missing one prime factor

    def test_is_multiply_prime_with_two_primes(self):
        self.assertFalse(is_multiply_prime(15))  # 3 * 5, not the product of three primes

    def test_is_multiply_prime_with_non_prime(self):
        self.assertFalse(is_multiply_prime(18))  # 2 * 3 * 3, two primes

    def test_is_multiply_prime_with_large_number(self):
        self.assertFalse(is_multiply_prime(200))  # just above the limit

    def test_is_multiply_prime_with_smallest_prime(self):
        self.assertFalse(is_multiply_prime(6))  # 2 * 3, not the product of three primes

    def test_is_multiply_prime_with_largest_prime(self):
        self.assertFalse(is_multiply_prime(97))  # largest prime less than 100

    def test_is_multiply_prime_with_product_of_three_primes(self):
        self.assertTrue(is_multiply_prime(30))  # 2 * 3 * 5

    def test_is_multiply_prime_with_non_prime_under_one_hundred(self):
        self.assertFalse(is_multiply_prime(1))  # not the product of primes

    def test_is_multiply_prime_with_non_prime_over_one_hundred(self):
        with self.assertRaises(TypeError):
            is_multiply_prime("not_a_number")  # type error for non-integer input

    def test_is_multiply_prime_with_negative_number(self):
        with self.assertRaises(TypeError):
            is_multiply_prime(-1)  # type error for negative input

    def test_is_multiply_prime_with_zero(self):
        with self.assertRaises(TypeError):
            is_multiply_prime(0)  # type error for zero input

if __name__ == '__main__':
    unittest.main()
